public boolean canHack(Entity entity, Player player) {
    return entity instanceof TamableAnimal t && !player.getUUID().equals(t.getOwnerUUID())
            || entity instanceof Horse h && !player.getUUID().equals(h.getOwnerUUID());
}

public int getHackTime(T entity, Player player) {
    return 60;
}

public void addHackInfo(T entity, List<Component> curInfo, Player player) {
    curInfo.add(xlate("pneumaticcraft.armor.hacking.result.tame"));
}

public void addPostHackInfo(T entity, List<Component> curInfo, Player player) {
    curInfo.add(xlate("pneumaticcraft.armor.hacking.finished.tamed"));
}

public Class<TamableAnimal> getHackableClass() {
    return TamableAnimal.class;
}

public void onHackFinished(TamableAnimal entity, Player player) {
    if (entity.level().isClientSide) {
        entity.handleEntityEvent((byte) 7);
    } else {
        entity.getNavigation().stop();
        entity.setTarget(null);
        entity.setHealth(20.0F);
        entity.setOwnerUUID(player.getUUID());
        entity.level().broadcastEntityEvent(entity, EntityEvent.TAMING_SUCCEEDED);
        entity.setTame(true, true);

        // TODO: code smell
        // Would be better to have a HackableCat subclass, but HackableHandler.getHackableForEntity() isn't
        // set up to prioritise getting a cat over a generic tameable.
        if (entity instanceof Cat cat) {
            BuiltInRegistries.CAT_VARIANT.getTag(CatVariantTags.DEFAULT_SPAWNS)
                    .flatMap(variants -> variants.getRandomElement(cat.level().getRandom()))
                    .ifPresent(cat::setVariant);
        }
    }
}

public Class<Horse> getHackableClass() {
    return Horse.class;
}

public void onHackFinished(Horse entity, Player player) {
    if (entity.level().isClientSide) {
        entity.handleEntityEvent((byte) 7);
    } else {
        entity.getNavigation().stop();
        entity.setTarget(null);
        entity.setHealth(20.0F);
        entity.setOwnerUUID(player.getUUID());
        entity.level().broadcastEntityEvent(entity, (byte) 7);
        entity.setTamed(true);
    }
}

public static IHackableEntity<?> getHackableForEntity(Entity entity, Player player) {
    HackManager manager = getInstance(player.level());

    // prune the tracked entities map every 60 ticks, removing dead or no-longer-hackable entities
    if (player.level().getGameTime() - 60 > manager.lastEntityPrune) {
        manager.hackableEntities.entrySet().removeIf(
                entry -> !entry.getKey().isAlive()
                        || !entry.getValue().canHack(entry.getKey(), player) && !isInDisplayCooldown(entry.getValue(), entry.getKey())
        );
        manager.lastEntityPrune = player.level().getGameTime();
    }

    // entities which implement IHackableEntity directly
    if (entity instanceof IHackableEntity<?> h && h.canHack(entity, player))
        return h;

    // entities which have been registered with the hack manager
    IHackableEntity<?> hackable = manager.hackableEntities.get(entity);
    if (hackable == null) {
        hackable = CommonArmorRegistry.getInstance().getHackable(entity, player);
        if (hackable != null) {
            manager.hackableEntities.put(entity, hackable);
        }
    }
    return hackable;
}

public IHackableEntity<?> getHackable(Entity entity, Player player) {
    if (!hackablesByType.containsKey(entity.getType())) {
        for (var entry : hackableEntities.entrySet()) {
            if (entry.getKey().isAssignableFrom(entity.getClass())) {
                hackablesByType.put(entity.getType(), entry.getValue().get());
            }
        }
    }

    return hackablesByType.get(entity.getType()).stream()
            .filter(hackable -> hackable.canHack(entity, player))
            .findFirst()
            .orElse(null);
}

default boolean canHack(Entity entity, Player player) {
    return entity.isAlive() && getHackableClass().isAssignableFrom(entity.getClass());
}

default int _getHackTime(Entity e, Player p) {
    //noinspection unchecked
    return getHackableClass().isAssignableFrom(e.getClass()) ? getHackTime((T) e, p) : -1;
}

default void _onHackFinished(Entity e, Player p) {
    if (getHackableClass().isAssignableFrom(e.getClass())) {
        //noinspection unchecked
        onHackFinished((T) e, p);
    }
}

private void tickEntityHack(ServerPlayer player) {
    IHackableEntity<?> hackableEntity = HackManager.getHackableForEntity(hackedEntity, player);
    if (hackableEntity != null) {
        int requiredTime = hackableEntity._getHackTime(hackedEntity, player);
        if (requiredTime <= 0) {
            setHackedEntity(null);
            return;
        }
        if (++hackTime >= requiredTime) {
            if (hackedEntity.isAlive()) {
                hackableEntity._onHackFinished(hackedEntity, player);
                HackTickTracker.getInstance(player.level()).trackEntity(hackedEntity, hackableEntity);
                NetworkHandler.sendToAllTracking(PacketHackingEntityFinish.forEntity(hackedEntity), hackedEntity);
                ModCriterionTriggers.ENTITY_HACK.get().trigger(player);
            }
            setHackedEntity(null);
        }
    } else {
        setHackedEntity(null);
    }
}

public void setHackedEntity(Entity entity) {
    hackedEntity = entity;
    hackedBlockPos = null;
    hackTime = 0;
}

public static void handle(PacketHackingEntityStart message, IPayloadContext ctx) {
    Player player = ctx.player();

    if (ctx.flow().isClientbound()) {
        // client
        Entity entity = player.level().getEntity(message.entityId());
        if (entity != null) {
            CommonArmorHandler.getHandlerForPlayer(player)
                    .getExtensionData(CommonUpgradeHandlers.hackHandler)
                    .setHackedEntity(entity);
            ClientArmorRegistry.getInstance()
                    .getClientHandler(CommonUpgradeHandlers.entityTrackerHandler, EntityTrackerClientHandler.class)
                    .getTargetsStream()
                    .filter(target -> target.entity == entity)
                    .findFirst()
                    .ifPresent(RenderEntityTarget::onHackConfirmServer);
        }
    } else if (player instanceof ServerPlayer sp) {
        // server
        CommonArmorHandler handler = CommonArmorHandler.getHandlerForPlayer(player);
        if (handler.upgradeUsable(CommonUpgradeHandlers.entityTrackerHandler, true)) {
            Entity entity = player.level().getEntity(message.entityId());
            if (entity != null) {
                handler.getExtensionData(CommonUpgradeHandlers.hackHandler).setHackedEntity(entity);
                NetworkHandler.sendToPlayer(message, sp);
            }
        }
    }
}

public static void handle(PacketHackingEntityFinish message, IPayloadContext ctx) {
    Player player = ctx.player();

    Entity entity = player.level().getEntity(message.entityId());
    if (entity != null) {
        IHackableEntity<?> hackableEntity = HackManager.getHackableForEntity(entity, player);
        if (hackableEntity != null) {
            hackableEntity._onHackFinished(entity, player);
            HackTickTracker.getInstance(entity.level()).trackEntity(entity, hackableEntity);
            CommonArmorHandler.getHandlerForPlayer(player).getExtensionData(CommonUpgradeHandlers.hackHandler).setHackedEntity(null);
            player.playSound(ModSounds.HELMET_HACK_FINISH.get(), 1.0F, 1.0F);
        }
    }
}

public void addInfo(Entity entity, List<Component> curInfo, boolean isLookingAtTarget) {
    Player player = ClientUtils.getClientPlayer();
    IHackableEntity<?> hackable = HackManager.getHackableForEntity(entity, player);
    if (hackable != null && hackable.getHackableClass().isAssignableFrom(entity.getClass())) {
        int hackTime = ClientArmorRegistry.getInstance()
                .getClientHandler(CommonUpgradeHandlers.entityTrackerHandler, EntityTrackerClientHandler.class)
                .getTargetsStream()
                .filter(target -> target.entity == entity)
                .findFirst()
                .map(RenderEntityTarget::getHackTime)
                .orElse(0);
        boolean entityTracked = HackTickTracker.getInstance(entity.level()).isEntityTracked(entity);
        if (hackTime == 0) {
            if (isLookingAtTarget && !entityTracked) {
                hackable._addHackInfo(entity, curInfo, player);
                HackClientHandler.addKeybindTooltip(curInfo);
            }
        } else {
            int requiredHackTime = hackable._getHackTime(entity, player);
            if (requiredHackTime > 0) {
                int percentageComplete = hackTime * 100 / requiredHackTime;
                if (percentageComplete < 100) {
                    curInfo.add(xlate("pneumaticcraft.armor.hacking.hacking", percentageComplete));
                } else if (hackTime < requiredHackTime + 20 || entityTracked) {
                    hackable._addPostHackInfo(entity, curInfo, player);
                } else if (isLookingAtTarget) {
                    hackable._addHackInfo(entity, curInfo, player);
                    HackClientHandler.addKeybindTooltip(curInfo);
                }
            }
        }
    }
}

